#!/bin/sh
# ios/ is generated by `expo prebuild` and ignored by git, so Xcode Cloud clones
# without the workspace. Build it here, before Xcode Cloud looks for it.
set -eu

export HOMEBREW_NO_AUTO_UPDATE=1 HOMEBREW_NO_INSTALL_CLEANUP=1 COREPACK_ENABLE_DOWNLOAD_PROMPT=0 CI=1
brew install node cocoapods
# Node 25+ no longer ships corepack; yarn.lock is Yarn 4.
npm install -g corepack

cd "$CI_PRIMARY_REPOSITORY_PATH"
corepack yarn@4.18.1 install --immutable
npx expo prebuild --platform ios
# Prebuild recreates ios/ and drops this folder; put it back so the tree stays clean.
git checkout -- ios/ci_scripts

# The JS bundle phase sources this file; EXPO_PUBLIC_ values are inlined at bundle time.
cat > ios/.xcode.env.local <<ENV
export NODE_BINARY="$(command -v node)"
export EXPO_PUBLIC_PROXY_URL=https://knowme-proxy.vercel.app
ENV
